#!/usr/bin/env bash
# Claude Code PreToolUse hook (Edit|Write|MultiEdit|NotebookEdit), wired in
# .claude/settings.json. The golden files record what archstats-ui and the
# scan digest depend on (e2eTest/testdata/snapshot_schema.golden,
# scan_digest.golden); one edited by hand passes the test while the engine
# writes something else. They are regenerated by their tests, never typed.
set -uo pipefail

command -v jq >/dev/null || exit 0
file="$(jq -r '.tool_input.file_path // .tool_input.notebook_path // empty')"

case "$file" in
  *.golden|*.golden.json)
    jq -n --arg r "$(basename "$file") is generated: regenerate it with UPDATE_GOLDEN=1 go test ./e2eTest -run 'TestSnapshotSchema|TestScanDigest' and review the diff. A schema change breaks archstats-ui; say so on the CHANGELOG line." \
      '{hookSpecificOutput: {hookEventName: "PreToolUse", permissionDecision: "deny", permissionDecisionReason: $r}}'
    ;;
esac
exit 0
